/* Blackboard lessons for the logic and sets cheat sheet: one lesson per card; the truth-table rows are keyed by number ('Propositions/#1').
   Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题', YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = 'Work it out on paper, type the answer (a fraction or a decimal) and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse (fraction ou décimal) et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta (fracción o decimal) y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答え（分数か小数）を入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案（分数或小数）并检查。每次提示会在黑板上写出解答的下一行。';
  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 26 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const Z = (x, y) => [x, y, 0];
  // give a group of scene items quick, staggered delays (the default is 300 ms per item, too slow for grids)
  const SEQ = (items, d0 = 200, step = 40) => items.map((a, i) => { const o = a[a.length - 1]; if (o && typeof o === 'object' && !Array.isArray(o)) o.d = d0 + i * step; return a; });
  const S2 = (c, r, axes = false) => ['3d', { flat: true, axes, c: [c[0], c[1], 0], r }];
  const CI = (o, r, c, fill = 0.16) => ['circ3', Z(...o), [0, 0, 1], r, { c, fill }];
  const LB = (p, t, c = 'y', size) => ['lab3', Z(...p), t, Object.assign({ c }, size ? { size } : {})];
  const SG = (p, q, c = 'chalk', o = {}) => ['seg', Z(...p), Z(...q), Object.assign({ c }, o)];
  const PT = (p, lab, c = 'y', o = {}) => ['pt3', Z(...p), lab || '', Object.assign({ c }, o)];
  const RECT = (x0, y0, x1, y1, c = 'b', fill = 0.3) => ['poly3', [Z(x0, y0), Z(x1, y0), Z(x1, y1), Z(x0, y1)], { c, fill }];
  // a Venn diagram of A and B inside the universe
  const VENN = (la = 'A', lb = 'B', extra = []) => [S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([-0.6, 0], 1.1, 'b'), CI([0.6, 0], 1.1, 'p'), LB([-1.3, 1.1], la, 'b'), LB([1.2, 1.1], lb, 'p'), LB([-2.2, 1.35], 'Ω', 'chalk'), ...extra], 200, 160)];
  // a two-level tree: first branch probability p (labels a, ā), then q1 / q2 for the event on each branch
  const TREE = (p, q1, q2, la, lb) => [S2([1.5, 0], 2.2), ...SEQ([
    SG([0, 0], [1.5, 1.2], 'b'), SG([0, 0], [1.5, -1.2], 'b'), SG([1.5, 1.2], [3, 1.8], 'y'), SG([1.5, 1.2], [3, 0.6], 'chalk'), SG([1.5, -1.2], [3, -0.6], 'y'), SG([1.5, -1.2], [3, -1.8], 'chalk'),
    LB([0.45, 0.85], p, 'b'), LB([0.45, -1.05], '1 − ' + p, 'b'), LB([1.5, 1.4], la[0], 'b'), LB([1.5, -1.0], la[1], 'b'),
    LB([2.0, 1.75], q1, 'y'), LB([2.0, -0.55], q2, 'y'), LB([3.1, 1.8], lb[0], 'y'), LB([3.1, 0.6], lb[1], 'chalk'), LB([3.1, -0.6], lb[0], 'y'), LB([3.1, -1.8], lb[1], 'chalk')], 200, 90)];
  // a bar chart: probabilities p[k] at x = k0 + k (height scaled by s)
  const BARS = (ps, k0 = 0, s = 1, c = 'b', hi = -1) => SEQ(ps.map((p, k) => RECT(k0 + k - 0.38, 0, k0 + k + 0.38, p * s, k === hi ? 'y' : c, k === hi ? 0.55 : 0.3)), 200, 70);
  const AX = (xw, yw) => ['ax', { xw, yw }], P = (eq, c = 'y', o = {}) => ['p', 'y=' + eq, Object.assign({ c }, o)], SH = (a, b) => ['sh', a, b];
  const N01 = 'e^(-x^2/2)/sqrt(2pi)';
  const L = {};
  const lesson = (key, head, idea, ex, your) => {
    L[key] = [{ t: IDEA, s: idea.s, a: [H(head), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(head), ...ex.a] },
      { t: YOUR, s: your.s || TRY, a: [['clr'], H(head), ...(your.a || [])], ex: your.ex }];
  };
  const C = (a, b) => { let r = 1; for (let k = 1; k <= b; k++) r = r * (a - b + k) / k; return r; };
  const binom = (n, p) => [...Array(n + 1)].map((_, k) => C(n, k) * p ** k * (1 - p) ** (n - k));

  const TRY_R = 'Type all the values separated by ; in any order (for example 2; 4; 6) and check. Each hint writes the next line of the solution.|Tapez toutes les valeurs séparées par ; dans n’importe quel ordre (par exemple 2; 4; 6) et vérifiez. Chaque indice écrit la ligne suivante.|Escribe todos los valores separados por ; en cualquier orden (por ejemplo 2; 4; 6) y comprueba. Cada pista escribe la siguiente línea.|すべての値を ; で区切って順不同で入力（例：2; 4; 6）して確かめよう。|输入所有值，用 ; 分隔，顺序不限（如 2; 4; 6），并检查。';
  const TRY_TF = 'Type 1 for true or 0 for false, then check. Each hint writes the next line of the reasoning.|Tapez 1 pour vrai ou 0 pour faux, puis vérifiez. Chaque indice écrit la ligne suivante du raisonnement.|Escribe 1 si es verdadero o 0 si es falso y comprueba. Cada pista escribe la siguiente línea del razonamiento.|真なら 1、偽なら 0 を入力して確かめよう。ヒントごとに推論が 1 行ずつ書かれます。|真输入 1，假输入 0，然后检查。每次提示写出推理的下一行。';
  // a Venn diagram where the listed regions are filled: 'a' (only A), 'b' (only B), 'ab' (both), 'out' (outside)
  const SHADE = (fillA, fillB, out = false) => [S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, out ? 'y' : 'chalk', out ? 0.35 : 0.03), CI([-0.6, 0], 1.1, fillA ? 'y' : 'b', fillA ? 0.45 : (out ? 0.9 : 0.12)), CI([0.6, 0], 1.1, fillB ? 'y' : 'p', fillB ? 0.45 : (out ? 0.9 : 0.12)), LB([-1.3, 1.1], 'A', 'b'), LB([1.2, 1.1], 'B', 'p'), LB([-2.2, 1.35], 'U', 'chalk')], 200, 140)];
  const LINE = (pieces, pts, c = [0, 0], r = 4) => [S2(c, r), SG([c[0] - r + 0.3, 0], [c[0] + r - 0.3, 0], 'chalk'), ...SEQ([...pieces.map(([a, b]) => SG([a, 0], [b, 0], 'y', { w: 5 })), ...pts.map(([x, closed, lab]) => PT([x, 0], lab, 'y', { hollow: !closed, dy: 22 }))], 200, 150)];
  const T1 = 'V|V|V|真|真', F0 = 'F|F|F|偽|假';

  // =============================== Sets ===============================
  lesson('Sets/Union and intersection', 'Union and intersection|Réunion et intersection|Unión e intersección|和集合と共通部分|并集与交集',
    { s: R`The union collects everything in $A$ or in $B$ (or both); the intersection keeps only what is in both. “Or” is inclusive in mathematics, so the common elements belong to the union — but count each element once.|La réunion rassemble tout ce qui est dans $A$ ou dans $B$ (ou les deux) ; l’intersection ne garde que ce qui est dans les deux. Le « ou » mathématique est inclusif : les éléments communs sont dans la réunion — comptés une seule fois.|La unión reúne todo lo que está en $A$ o en $B$ (o en ambos); la intersección solo lo que está en los dos. El «o» matemático es inclusivo: los comunes están en la unión, contados una vez.|和集合は $A$ または $B$（両方も含む）の要素すべて、共通部分は両方にある要素だけ。数学の「または」は両方を含む。共通の要素は 1 回だけ数える。|并集包含在 $A$ 或 $B$（或两者）中的一切；交集只保留两者都有的。数学中的“或”是可兼的，公共元素属于并集——但只算一次。`,
      a: [Y(R`A \cup B:\ x \in A \lor x \in B,\qquad A \cap B:\ x \in A \land x \in B`, { s: 22 }), ...VENN('A', 'B', [LB([-0.12, 0], 'A∩B', 'y')])] },
    { s: R`$A = \{1, 2, 3, 4\}$, $B = \{3, 4, 5\}$: $A \cup B = \{1, 2, 3, 4, 5\}$ and $A \cap B = \{3, 4\}$.|$A = \{1, 2, 3, 4\}$, $B = \{3, 4, 5\}$ : $A \cup B = \{1, 2, 3, 4, 5\}$ et $A \cap B = \{3, 4\}$.|$A = \{1, 2, 3, 4\}$, $B = \{3, 4, 5\}$: $A \cup B = \{1, 2, 3, 4, 5\}$ y $A \cap B = \{3, 4\}$.|$A \cup B = \{1, \dots, 5\}$、$A \cap B = \{3, 4\}$。|$A \cup B = \{1, \dots, 5\}$，$A \cap B = \{3, 4\}$。`,
      a: [F(R`A \cup B = \{1, 2, 3, 4, 5\}`), Y(R`A \cap B = \{3, 4\}`), ...VENN('A', 'B', [LB([-1.1, 0], '1, 2', 'chalk'), LB([0, 0], '3, 4', 'y'), LB([1.1, 0], '5', 'chalk')])] },
    { s: TRY_R, a: [F(R`A = \{1, 2, 3, 4, 5, 6\},\quad B = \{2, 4, 6, 8\}`)],
      ex: { k: 'roots', v: [2, 4, 6], q: R`$A = \{1, 2, 3, 4, 5, 6\}$, $B = \{2, 4, 6, 8\}$. List the elements of $A \cap B$.|$A = \{1, 2, 3, 4, 5, 6\}$, $B = \{2, 4, 6, 8\}$. Donnez les éléments de $A \cap B$.|$A = \{1, 2, 3, 4, 5, 6\}$, $B = \{2, 4, 6, 8\}$. Da los elementos de $A \cap B$.|$A = \{1, 2, 3, 4, 5, 6\}$, $B = \{2, 4, 6, 8\}$。$A \cap B$ の要素を答えよ。|$A = \{1, 2, 3, 4, 5, 6\}$，$B = \{2, 4, 6, 8\}$，写出 $A \cap B$ 的元素。`, sol: [R`\text{in both: } 2, 4, 6`, R`A \cap B = \{2, 4, 6\}`] } });

  lesson('Sets/Complement and difference', 'Complement and difference|Complémentaire et différence|Complemento y diferencia|補集合と差集合|补集与差集',
    { s: R`The complement $\bar A$ is everything in the universe $U$ that is not in $A$. The difference $A \setminus B$ removes from $A$ whatever is also in $B$ — the same as $A \cap \bar B$. Order matters: $A \setminus B \ne B \setminus A$.|Le complémentaire $\bar A$ est tout ce qui est dans l’univers $U$ mais pas dans $A$. La différence $A \setminus B$ retire de $A$ ce qui est aussi dans $B$ — c’est $A \cap \bar B$. L’ordre compte : $A \setminus B \ne B \setminus A$.|El complemento $\bar A$ es todo lo del universo $U$ que no está en $A$. La diferencia $A \setminus B$ quita de $A$ lo que también está en $B$: es $A \cap \bar B$. El orden importa: $A \setminus B \ne B \setminus A$.|補集合 $\bar A$ は全体 $U$ のうち $A$ にないもの。差 $A \setminus B$ は $A$ から $B$ にもあるものを除く（$A \cap \bar B$）。順序が大事。|补集 $\bar A$ 是全集 $U$ 中不在 $A$ 里的元素。差集 $A \setminus B$ 从 $A$ 去掉也在 $B$ 中的——即 $A \cap \bar B$。顺序重要。`,
      a: [Y(R`\bar A = U \setminus A,\qquad A \setminus B = A \cap \bar B`), S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([-0.6, 0], 1.1, 'y', 0.45), CI([0.6, 0], 1.1, 'p', 0.85), LB([-1.1, 0], 'A∖B', 'chalk'), LB([-1.3, 1.1], 'A', 'y'), LB([1.2, 1.1], 'B', 'p'), LB([-2.2, 1.35], 'U', 'chalk')], 200, 140)] },
    { s: R`$U = \{1, \dots, 10\}$, $A$ = even numbers: $\bar A = \{1, 3, 5, 7, 9\}$. With $B = \{1, 2, 3\}$: $A \setminus B = \{4, 6, 8, 10\}$.|$U = \{1, \dots, 10\}$, $A$ = pairs : $\bar A = \{1, 3, 5, 7, 9\}$. Avec $B = \{1, 2, 3\}$ : $A \setminus B = \{4, 6, 8, 10\}$.|$U = \{1, \dots, 10\}$, $A$ = pares: $\bar A = \{1, 3, 5, 7, 9\}$. Con $B = \{1, 2, 3\}$: $A \setminus B = \{4, 6, 8, 10\}$.|$\bar A$ は奇数、$A \setminus B = \{4, 6, 8, 10\}$。|$\bar A$ 为奇数，$A \setminus B = \{4, 6, 8, 10\}$。`,
      a: [F(R`\bar A = \{1, 3, 5, 7, 9\}`), Y(R`A \setminus B = \{4, 6, 8, 10\}`)] },
    { s: TRY_R, a: [F(R`A = \{1, 2, 3, 4\},\quad B = \{3, 4, 5\}`)],
      ex: { k: 'roots', v: [1, 2], q: R`$A = \{1, 2, 3, 4\}$ and $B = \{3, 4, 5\}$. List the elements of $A \setminus B$.|$A = \{1, 2, 3, 4\}$ et $B = \{3, 4, 5\}$. Donnez les éléments de $A \setminus B$.|$A = \{1, 2, 3, 4\}$ y $B = \{3, 4, 5\}$. Da los elementos de $A \setminus B$.|$A \setminus B$ の要素を答えよ。|写出 $A \setminus B$ 的元素。`, sol: [R`\text{remove } 3, 4`, R`A \setminus B = \{1, 2\}`] } });

  lesson('Sets/De Morgan’s laws', 'De Morgan’s laws|Lois de De Morgan|Leyes de De Morgan|ド・モルガンの法則|德摩根律',
    { s: R`“Not in ($A$ or $B$)” means outside both circles: not in $A$ and not in $B$. Complementing swaps $\cup$ and $\cap$. The shaded region outside both circles is $\overline{A \cup B} = \bar A \cap \bar B$.|« Pas dans ($A$ ou $B$) » signifie hors des deux cercles : ni dans $A$ ni dans $B$. Passer au complémentaire échange $\cup$ et $\cap$. La zone hachurée hors des deux cercles est $\overline{A \cup B} = \bar A \cap \bar B$.|«No estar en ($A$ o $B$)» es estar fuera de los dos círculos: ni en $A$ ni en $B$. Tomar el complemento intercambia $\cup$ y $\cap$. La zona sombreada fuera de ambos es $\overline{A \cup B} = \bar A \cap \bar B$.|「（$A$ または $B$）でない」は両方の円の外：$A$ でなく $B$ でもない。補集合をとると $\cup$ と $\cap$ が入れ替わる。|“不在（$A$ 或 $B$）中”即在两圆之外：既不在 $A$ 也不在 $B$。取补集交换 $\cup$ 与 $\cap$。`,
      a: [Y(R`\overline{A \cup B} = \bar A \cap \bar B,\qquad \overline{A \cap B} = \bar A \cup \bar B`, { s: 22 }), ...SHADE(false, false, true)] },
    { s: R`Students who play neither football nor tennis = not football AND not tennis. Students who do not play both = not football OR not tennis.|Les élèves qui ne font ni foot ni tennis = pas foot ET pas tennis. Ceux qui ne font pas les deux = pas foot OU pas tennis.|Alumnos que no juegan ni al fútbol ni al tenis = no fútbol Y no tenis. Los que no juegan a ambos = no fútbol O no tenis.|「どちらもしない」＝しない かつ しない。「両方はしない」＝しない または しない。|“都不玩”＝不玩足球且不玩网球；“不都玩”＝不玩足球或不玩网球。`,
      a: [Y(R`\overline{F \cup T} = \bar F \cap \bar T`)] },
    { a: [F(R`\lvert U\rvert = 40,\quad \lvert A \cup B\rvert = 28`)],
      ex: { k: 'val', v: '12', q: R`$\lvert U\rvert = 40$ and $\lvert A \cup B\rvert = 28$. Find $\lvert\bar A \cap \bar B\rvert$.|$\lvert U\rvert = 40$ et $\lvert A \cup B\rvert = 28$. Calculez $\lvert\bar A \cap \bar B\rvert$.|$\lvert U\rvert = 40$ y $\lvert A \cup B\rvert = 28$. Halla $\lvert\bar A \cap \bar B\rvert$.|$\lvert U\rvert = 40$, $\lvert A \cup B\rvert = 28$ のとき $\lvert\bar A \cap \bar B\rvert$ を求めよ。|$\lvert U\rvert = 40$，$\lvert A \cup B\rvert = 28$，求 $\lvert\bar A \cap \bar B\rvert$。`, sol: [R`\bar A \cap \bar B = \overline{A \cup B}`, R`40 - 28 = 12`] } });

  lesson('Sets/Distributive laws', 'Distributive laws|Distributivité|Leyes distributivas|分配法則|分配律',
    { s: R`$\cap$ distributes over $\cup$ like multiplication over addition — and, unlike numbers, $\cup$ also distributes over $\cap$. Check with a three-circle diagram: both sides shade the same region.|$\cap$ se distribue sur $\cup$ comme la multiplication sur l’addition — et, contrairement aux nombres, $\cup$ se distribue aussi sur $\cap$. On vérifie avec trois cercles : les deux membres hachurent la même zone.|$\cap$ se distribuye sobre $\cup$ como el producto sobre la suma y, a diferencia de los números, $\cup$ también se distribuye sobre $\cap$. Compruébalo con tres círculos: ambos lados sombrean la misma región.|$\cap$ は $\cup$ に対して（掛け算が足し算に対するように）分配され、さらに $\cup$ も $\cap$ に分配される。3 つの円で両辺が同じ領域になることを確かめよう。|$\cap$ 对 $\cup$ 分配，如同乘法对加法；与数不同，$\cup$ 对 $\cap$ 也分配。用三个圆验证：两边阴影相同。`,
      a: [Y(R`A \cap (B \cup C) = (A \cap B) \cup (A \cap C)`, { s: 22 }), S2([0, -0.2], 2.2), ...SEQ([CI([0, 0.5], 1, 'y', 0.35), CI([-0.6, -0.5], 1, 'b'), CI([0.6, -0.5], 1, 'p'), LB([0, 1.25], 'A', 'y'), LB([-1.4, -1.2], 'B', 'b'), LB([1.4, -1.2], 'C', 'p')], 200, 160)] },
    { s: R`$A = \{1, 2, 3\}$, $B = \{2, 4\}$, $C = \{3, 4\}$: $B \cup C = \{2, 3, 4\}$, so $A \cap (B \cup C) = \{2, 3\}$; and $(A \cap B) \cup (A \cap C) = \{2\} \cup \{3\}$ — the same.|$B \cup C = \{2, 3, 4\}$, donc $A \cap (B \cup C) = \{2, 3\}$ ; et $\{2\} \cup \{3\}$ — pareil.|$B \cup C = \{2, 3, 4\}$, así que $A \cap (B \cup C) = \{2, 3\}$; y $\{2\} \cup \{3\}$, lo mismo.|両辺とも $\{2, 3\}$。|两边都是 $\{2, 3\}$。`,
      a: [F(R`A \cap \{2, 3, 4\} = \{2, 3\}`), Y(R`\{2\} \cup \{3\} = \{2, 3\}`)] },
    { s: TRY_R, a: [F(R`A = \{1, 2, 3, 5\},\ B = \{2, 5, 7\},\ C = \{1, 7\}`)],
      ex: { k: 'roots', v: [1, 2, 5], q: R`$A = \{1, 2, 3, 5\}$, $B = \{2, 5, 7\}$, $C = \{1, 7\}$. List the elements of $A \cap (B \cup C)$.|$A = \{1, 2, 3, 5\}$, $B = \{2, 5, 7\}$, $C = \{1, 7\}$. Donnez les éléments de $A \cap (B \cup C)$.|$A = \{1, 2, 3, 5\}$, $B = \{2, 5, 7\}$, $C = \{1, 7\}$. Da los elementos de $A \cap (B \cup C)$.|$A \cap (B \cup C)$ の要素を答えよ。|写出 $A \cap (B \cup C)$ 的元素。`, sol: [R`B \cup C = \{1, 2, 5, 7\}`, R`A \cap (B \cup C) = \{1, 2, 5\}`] } });

  lesson('Sets/Subsets', 'Subsets|Inclusion|Subconjuntos|部分集合|子集',
    { s: R`$A \subseteq B$ means every element of $A$ is in $B$: the circle $A$ sits inside $B$. Then intersecting with $B$ changes nothing in $A$, and adding $A$ to $B$ changes nothing in $B$. A set with $n$ elements has $2^n$ subsets (each element in or out).|$A \subseteq B$ signifie que tout élément de $A$ est dans $B$ : le cercle $A$ est dans $B$. Alors $A \cap B = A$ et $A \cup B = B$. Un ensemble à $n$ éléments a $2^n$ parties (chaque élément dedans ou dehors).|$A \subseteq B$ significa que todo elemento de $A$ está en $B$: el círculo $A$ queda dentro de $B$. Entonces $A \cap B = A$ y $A \cup B = B$. Un conjunto de $n$ elementos tiene $2^n$ subconjuntos (cada elemento está o no).|$A \subseteq B$ は $A$ の要素がすべて $B$ にあること（円 $A$ が $B$ の中）。このとき $A \cap B = A$、$A \cup B = B$。$n$ 元集合の部分集合は $2^n$ 個。|$A \subseteq B$ 表示 $A$ 的每个元素都在 $B$ 中：圆 $A$ 在 $B$ 内。于是 $A \cap B = A$，$A \cup B = B$。$n$ 元集合有 $2^n$ 个子集。`,
      a: [Y(R`A \subseteq B \iff A \cap B = A \iff A \cup B = B`, { s: 22 }), S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([0, 0], 1.4, 'p'), CI([-0.4, 0], 0.7, 'y', 0.35), LB([-0.4, 0], 'A', 'chalk'), LB([0.9, 0.9], 'B', 'p')], 200, 150)] },
    { s: R`$\{a, b, c\}$ has $2^3 = 8$ subsets: $\varnothing$, $\{a\}$, $\{b\}$, $\{c\}$, $\{a, b\}$, $\{a, c\}$, $\{b, c\}$, $\{a, b, c\}$.|$\{a, b, c\}$ a $2^3 = 8$ parties.|$\{a, b, c\}$ tiene $2^3 = 8$ subconjuntos.|$2^3 = 8$ 個。|$2^3 = 8$ 个。`,
      a: [Y(R`2^3 = 8`)] },
    { a: [F(R`\{a, b, c, d\}`)],
      ex: { k: 'val', v: '8', q: R`How many subsets of $\{a, b, c, d\}$ contain $a$?|Combien de parties de $\{a, b, c, d\}$ contiennent $a$ ?|¿Cuántos subconjuntos de $\{a, b, c, d\}$ contienen $a$?|$\{a, b, c, d\}$ の部分集合のうち $a$ を含むものは何個か。|$\{a, b, c, d\}$ 中含 $a$ 的子集有几个？`, sol: [R`a\ \text{in; } b, c, d\ \text{free}`, R`2^3 = 8`] } });

  lesson('Sets/Counting', 'Counting elements|Compter les éléments|Contar elementos|要素の個数|元素个数',
    { s: R`Counting $A$ and then $B$ counts the common part twice, so subtract it once. Knowing any three of $\lvert A\rvert$, $\lvert B\rvert$, $\lvert A \cap B\rvert$, $\lvert A \cup B\rvert$ gives the fourth.|En comptant $A$ puis $B$ on compte deux fois la partie commune : on la retire une fois. Trois des nombres $\lvert A\rvert$, $\lvert B\rvert$, $\lvert A \cap B\rvert$, $\lvert A \cup B\rvert$ donnent le quatrième.|Al contar $A$ y luego $B$ se cuenta dos veces la parte común: réstala una vez. Con tres de $\lvert A\rvert$, $\lvert B\rvert$, $\lvert A \cap B\rvert$, $\lvert A \cup B\rvert$ se obtiene el cuarto.|$A$ と $B$ を数えると共通部分を 2 回数えるので 1 回引く。4 つの量のうち 3 つから残り 1 つが出る。|先数 $A$ 再数 $B$，公共部分数了两次，减一次。四个量知道三个就能求第四个。`,
      a: [Y(R`\lvert A \cup B\rvert = \lvert A\rvert + \lvert B\rvert - \lvert A \cap B\rvert`, { s: 22 }), ...VENN('A', 'B', [LB([-1.1, 0], '13', 'chalk'), LB([0, 0], '7', 'y'), LB([1.1, 0], '8', 'chalk')])] },
    { s: R`In a class, 20 study French, 15 study German and 7 study both: $20 + 15 - 7 = 28$ study at least one.|20 étudient le français, 15 l’allemand, 7 les deux : $28$ en étudient au moins une.|20 estudian francés, 15 alemán y 7 ambos: $28$ estudian al menos uno.|$20 + 15 - 7 = 28$。|$20 + 15 - 7 = 28$。`,
      a: [Y(R`20 + 15 - 7 = 28`)] },
    { a: [F(R`\lvert A\rvert = 20,\ \lvert B\rvert = 15,\ \lvert A \cup B\rvert = 28`)],
      ex: { k: 'val', v: '7', q: R`$\lvert A\rvert = 20$, $\lvert B\rvert = 15$, $\lvert A \cup B\rvert = 28$. Find $\lvert A \cap B\rvert$.|$\lvert A\rvert = 20$, $\lvert B\rvert = 15$, $\lvert A \cup B\rvert = 28$. Calculez $\lvert A \cap B\rvert$.|$\lvert A\rvert = 20$, $\lvert B\rvert = 15$, $\lvert A \cup B\rvert = 28$. Halla $\lvert A \cap B\rvert$.|$\lvert A \cap B\rvert$ を求めよ。|求 $\lvert A \cap B\rvert$。`, sol: [R`\lvert A \cap B\rvert = 20 + 15 - 28`, R`= 7`] } });

  lesson('Sets/Number sets', 'Number sets|Ensembles de nombres|Conjuntos numéricos|数の集合|数集',
    { s: R`Each set extends the previous one to allow a new operation: $\mathbb Z$ adds negatives (subtraction), $\mathbb Q$ fractions (division), $\mathbb R$ limits like $\sqrt2$ and $\pi$, $\mathbb C$ square roots of negatives. Classify a number by its simplest form: $\sqrt9 = 3$ is a natural number.|Chaque ensemble prolonge le précédent pour permettre une nouvelle opération : $\mathbb Z$ ajoute les négatifs (soustraction), $\mathbb Q$ les fractions (division), $\mathbb R$ les limites comme $\sqrt2$ et $\pi$, $\mathbb C$ les racines de négatifs. On classe un nombre d’après sa forme la plus simple : $\sqrt9 = 3$ est un entier naturel.|Cada conjunto amplía el anterior para permitir una operación nueva: $\mathbb Z$ añade negativos (resta), $\mathbb Q$ fracciones (división), $\mathbb R$ límites como $\sqrt2$ y $\pi$, $\mathbb C$ raíces de negativos. Clasifica un número por su forma más simple: $\sqrt9 = 3$ es natural.|各集合は新しい演算のために前の集合を広げたもの：$\mathbb Z$ は負の数、$\mathbb Q$ は分数、$\mathbb R$ は $\sqrt2$ や $\pi$、$\mathbb C$ は負の数の平方根。最も簡単な形で分類（$\sqrt9 = 3$ は自然数）。|每个数集扩充前一个以允许新运算：$\mathbb Z$ 加入负数，$\mathbb Q$ 加入分数，$\mathbb R$ 加入 $\sqrt2$、$\pi$ 等，$\mathbb C$ 加入负数的平方根。按最简形式分类：$\sqrt9 = 3$ 是自然数。`,
      a: [Y(R`\mathbb N \subset \mathbb Z \subset \mathbb Q \subset \mathbb R \subset \mathbb C`, { s: 30 }), S2([0, 0], 2.4), ...SEQ([CI([0, 0], 2.2, 'g', 0.06), CI([-0.3, 0], 1.75, 'p', 0.06), CI([-0.6, 0], 1.3, 'b', 0.06), CI([-0.9, 0], 0.8, 'y', 0.12), LB([-0.9, 0], 'ℕ', 'y'), LB([0.35, 0], 'ℤ', 'b'), LB([1.05, 0.4], 'ℚ', 'p'), LB([1.65, 0.6], 'ℝ', 'g')], 200, 140)] },
    { s: R`$-3 \in \mathbb Z \setminus \mathbb N$; $\tfrac25 \in \mathbb Q \setminus \mathbb Z$; $\sqrt2, \pi \in \mathbb R \setminus \mathbb Q$ (irrational); $\sqrt{-1} = i \in \mathbb C \setminus \mathbb R$.|$-3 \in \mathbb Z \setminus \mathbb N$ ; $\tfrac25 \in \mathbb Q \setminus \mathbb Z$ ; $\sqrt2, \pi$ irrationnels ; $i \in \mathbb C \setminus \mathbb R$.|$-3 \in \mathbb Z \setminus \mathbb N$; $\tfrac25 \in \mathbb Q \setminus \mathbb Z$; $\sqrt2, \pi$ irracionales; $i \in \mathbb C \setminus \mathbb R$.|$\sqrt2, \pi$ は無理数。|$\sqrt2, \pi$ 是无理数。`,
      a: [Y(R`-3 \in \mathbb Z,\quad \tfrac25 \in \mathbb Q,\quad \sqrt2 \in \mathbb R \setminus \mathbb Q`, { s: 24 })] },
    { a: [F(R`-2,\ \ 0.5,\ \ \sqrt9,\ \ \pi,\ \ \tfrac34,\ \ -\sqrt4`)],
      ex: { k: 'val', v: '3', q: R`How many of the numbers $-2,\ 0.5,\ \sqrt9,\ \pi,\ \tfrac34,\ -\sqrt4$ are integers?|Combien des nombres $-2,\ 0{,}5,\ \sqrt9,\ \pi,\ \tfrac34,\ -\sqrt4$ sont des entiers ?|¿Cuántos de los números $-2,\ 0{,}5,\ \sqrt9,\ \pi,\ \tfrac34,\ -\sqrt4$ son enteros?|$-2,\ 0.5,\ \sqrt9,\ \pi,\ \tfrac34,\ -\sqrt4$ のうち整数は何個か。|$-2,\ 0.5,\ \sqrt9,\ \pi,\ \tfrac34,\ -\sqrt4$ 中有几个整数？`, sol: [R`\sqrt9 = 3,\quad -\sqrt4 = -2`, R`-2,\ 3,\ -2:\ 3\ \text{integers}`] } });

  lesson('Sets/Intervals', 'Intervals|Intervalles|Intervalos|区間|区间',
    { s: R`An interval is a piece of the number line. A square bracket includes the endpoint (filled dot), a round one excludes it (hollow dot); $\infty$ always gets a round bracket. Intersections of intervals are the overlap.|Un intervalle est un morceau de la droite réelle. Un crochet tourné vers le nombre l’inclut (point plein), sinon il l’exclut (point vide) ; $\infty$ n’est jamais inclus. L’intersection d’intervalles est leur partie commune.|Un intervalo es un trozo de la recta real. El corchete incluye el extremo (punto relleno) y el paréntesis lo excluye (punto hueco); $\infty$ siempre lleva paréntesis. La intersección de intervalos es la parte común.|区間は数直線の一部。角かっこは端点を含み（黒丸）、丸かっこは含まない（白丸）。$\infty$ は常に丸かっこ。共通部分は重なり。|区间是数轴的一段。方括号包含端点（实心点），圆括号不含（空心点）；$\infty$ 总用圆括号。区间的交集是重叠部分。`,
      a: [Y(R`[a, b] = \{a \le x \le b\},\quad (a, b) = \{a < x < b\}`, { s: 24 }), ...LINE([[-1, 3]], [[-1, true, '−1'], [3, false, '3']], [1, 0], 3.5)] },
    { s: R`$[-1, 3) \cap (0, 5] = (0, 3)$: the overlap starts after 0 (excluded by the second) and stops before 3 (excluded by the first).|$[-1, 3) \cap (0, 5] = (0, 3)$ : la partie commune commence après 0 et s’arrête avant 3.|$[-1, 3) \cap (0, 5] = (0, 3)$: la parte común empieza después de 0 y termina antes de 3.|$(0, 3)$。|$(0, 3)$。`,
      a: [Y(R`[-1, 3) \cap (0, 5] = (0, 3)`), ...LINE([[0, 3]], [[0, false, '0'], [3, false, '3']], [2, 0], 4)] },
    { a: [F(R`[-2, 3)`), ...LINE([[-2, 3]], [[-2, true, '−2'], [3, false, '3']], [0.5, 0], 3.5)],
      ex: { k: 'val', v: '5', q: R`How many integers lie in the interval $[-2, 3)$?|Combien d’entiers sont dans l’intervalle $[-2, 3)$ ?|¿Cuántos enteros hay en el intervalo $[-2, 3)$?|区間 $[-2, 3)$ に整数は何個あるか。|区间 $[-2, 3)$ 中有几个整数？`, sol: [R`-2,\ -1,\ 0,\ 1,\ 2\quad (3\ \text{excluded})`, R`5`] } });

  // =============================== Propositions: the truth-table rows ===============================
  const ROW = (n, p, q, vals, count, en, fr, es, ja, zh) => lesson('Propositions/#' + n, `Truth table: p = ${p}, q = ${q}|Table de vérité : p = ${p}, q = ${q}|Tabla de verdad: p = ${p}, q = ${q}|真理値表：p = ${p}, q = ${q}|真值表：p = ${p}, q = ${q}`,
    { s: [en, fr, es, ja, zh].join('|'), a: [F(R`p = \text{${p}},\quad q = \text{${q}}`), Y(R`\lnot p = \text{${vals[0]}},\ \ p \land q = \text{${vals[1]}},\ \ p \lor q = \text{${vals[2]}}`, { s: 22 }), Y(R`p \Rightarrow q = \text{${vals[3]}},\ \ p \Leftrightarrow q = \text{${vals[4]}}`, { s: 22 })] },
    { s: R`Read “and” as both, “or” as at least one, “$\Rightarrow$” as a promise that is broken only when $p$ is true and $q$ is false, and “$\Leftrightarrow$” as “same value”.|Lisez « et » : les deux ; « ou » : au moins un ; « $\Rightarrow$ » : une promesse qui n’est rompue que si $p$ est vraie et $q$ fausse ; « $\Leftrightarrow$ » : même valeur.|Lee «y» como ambos, «o» como al menos uno, «$\Rightarrow$» como una promesa que solo se rompe si $p$ es verdadera y $q$ falsa, y «$\Leftrightarrow$» como «mismo valor».|「かつ」は両方、「または」は少なくとも一方、「$\Rightarrow$」は $p$ 真で $q$ 偽のときだけ破られる約束、「$\Leftrightarrow$」は同じ値。|“且”是两者都，“或”是至少一个，“$\Rightarrow$”是只在 $p$ 真 $q$ 假时被违背的承诺，“$\Leftrightarrow$”是取值相同。`,
      a: [F(R`\land:\ \text{both}\qquad \lor:\ \text{at least one}`), F(R`p \Rightarrow q\ \text{false only for } p = \text{T},\ q = \text{F}`, { s: 22 }), Y(R`p \Leftrightarrow q:\ \text{same value}`)] },
    { s: 'Count and type a number, then check.|Comptez, tapez un nombre et vérifiez.|Cuenta, escribe un número y comprueba.|数えて数を入力し確かめよう。|数一数，输入数字并检查。', a: [F(R`p = \text{${p}},\quad q = \text{${q}}`)],
      ex: { k: 'val', v: String(count), q: `In the row p = ${p}, q = ${q}, how many of the five statements ¬p, p ∧ q, p ∨ q, p ⇒ q, p ⇔ q are true?|Dans la ligne p = ${p}, q = ${q}, combien des cinq propositions ¬p, p ∧ q, p ∨ q, p ⇒ q, p ⇔ q sont vraies ?|En la fila p = ${p}, q = ${q}, ¿cuántas de las cinco proposiciones ¬p, p ∧ q, p ∨ q, p ⇒ q, p ⇔ q son verdaderas?|p = ${p}, q = ${q} の行で ¬p, p ∧ q, p ∨ q, p ⇒ q, p ⇔ q のうち真はいくつか。|在 p = ${p}、q = ${q} 这一行，¬p、p ∧ q、p ∨ q、p ⇒ q、p ⇔ q 中有几个为真？`,
        sol: [R`\text{${vals.join(',\\ ')}}`, R`${count}\ \text{true}`] } });
  ROW(1, 'T', 'T', ['F', 'T', 'T', 'T', 'T'], 4, 'Both statements true: everything except ¬p is true. An implication with a true hypothesis and a true conclusion is kept.', 'Les deux propositions vraies : tout est vrai sauf ¬p. Une implication d’hypothèse vraie et de conclusion vraie est respectée.', 'Ambas verdaderas: todo es verdadero salvo ¬p. Una implicación con hipótesis y conclusión verdaderas se cumple.', '両方とも真：¬p 以外はすべて真。仮定も結論も真の含意は守られている。', '两个都真：除 ¬p 外都为真。前提真、结论真的蕴含成立。');
  ROW(2, 'T', 'F', ['F', 'F', 'T', 'F', 'F'], 1, 'p true, q false: the only row where p ⇒ q is false — the promise “if p then q” was broken. Only p ∨ q survives.', 'p vraie, q fausse : la seule ligne où p ⇒ q est fausse — la promesse « si p alors q » est rompue. Seule p ∨ q est vraie.', 'p verdadera, q falsa: la única fila en la que p ⇒ q es falsa; la promesa «si p entonces q» se rompió. Solo p ∨ q es verdadera.', 'p 真、q 偽：p ⇒ q が偽になる唯一の行（「p ならば q」の約束が破られた）。真は p ∨ q だけ。', 'p 真 q 假：p ⇒ q 唯一为假的一行——“若 p 则 q”被违背。只有 p ∨ q 为真。');
  ROW(3, 'F', 'T', ['T', 'F', 'T', 'T', 'F'], 3, 'p false, q true: p ⇒ q is true — a promise about the case p is not broken when p does not happen. The values differ, so p ⇔ q is false.', 'p fausse, q vraie : p ⇒ q est vraie — une promesse sur le cas p n’est pas rompue quand p n’arrive pas. Les valeurs diffèrent, donc p ⇔ q est fausse.', 'p falsa, q verdadera: p ⇒ q es verdadera; una promesa sobre el caso p no se rompe si p no ocurre. Los valores difieren, así que p ⇔ q es falsa.', 'p 偽、q 真：p ⇒ q は真（p が起きなければ約束は破られない）。値が違うので p ⇔ q は偽。', 'p 假 q 真：p ⇒ q 为真——p 不发生时承诺未被违背。取值不同，p ⇔ q 为假。');
  ROW(4, 'F', 'F', ['T', 'F', 'F', 'T', 'T'], 3, 'Both false: “and” and “or” are false, but p ⇒ q is true (vacuously) and p ⇔ q is true because both have the same value.', 'Les deux fausses : « et » et « ou » sont faux, mais p ⇒ q est vraie (trivialement) et p ⇔ q aussi, car les deux ont la même valeur.', 'Ambas falsas: «y» y «o» son falsas, pero p ⇒ q es verdadera (trivialmente) y p ⇔ q también, porque tienen el mismo valor.', '両方偽：「かつ」「または」は偽だが p ⇒ q は（空虚に）真、p ⇔ q も同じ値なので真。', '两个都假：“且”“或”为假，但 p ⇒ q（空真）为真，p ⇔ q 因取值相同也为真。');

  lesson('Propositions/Negations', 'Negating and / or|Négation de « et » / « ou »|Negar «y» / «o»|「かつ」「または」の否定|否定“且”与“或”',
    { s: R`To deny “$p$ and $q$” it is enough that one of them fails: $\lnot p \lor \lnot q$. To deny “$p$ or $q$” both must fail: $\lnot p \land \lnot q$. Negation swaps $\land$ and $\lor$ — De Morgan again.|Pour nier « $p$ et $q$ », il suffit que l’une soit fausse : $\lnot p \lor \lnot q$. Pour nier « $p$ ou $q$ », il faut que les deux le soient : $\lnot p \land \lnot q$. La négation échange $\land$ et $\lor$ — encore De Morgan.|Para negar «$p$ y $q$» basta con que falle una: $\lnot p \lor \lnot q$. Para negar «$p$ o $q$» deben fallar las dos: $\lnot p \land \lnot q$. La negación intercambia $\land$ y $\lor$: De Morgan otra vez.|「$p$ かつ $q$」の否定は一方が偽で十分：$\lnot p \lor \lnot q$。「$p$ または $q$」の否定は両方偽：$\lnot p \land \lnot q$。否定で $\land$ と $\lor$ が入れ替わる（ド・モルガン）。|否定“$p$ 且 $q$”只需一个不成立：$\lnot p \lor \lnot q$。否定“$p$ 或 $q$”需两个都不成立：$\lnot p \land \lnot q$。否定交换 $\land$ 与 $\lor$——又是德摩根。`,
      a: [Y(R`\lnot(p \land q) \equiv \lnot p \lor \lnot q`), Y(R`\lnot(p \lor q) \equiv \lnot p \land \lnot q`)] },
    { s: R`“It is not true that it is sunny and warm” = “it is not sunny or it is not warm”. “$x < 0$ or $x > 5$” is negated as “$x \ge 0$ and $x \le 5$”, i.e. $0 \le x \le 5$.|« Il n’est pas vrai qu’il fasse beau et chaud » = « il ne fait pas beau ou pas chaud ». « $x < 0$ ou $x > 5$ » se nie en $0 \le x \le 5$.|«No es cierto que haga sol y calor» = «no hace sol o no hace calor». «$x < 0$ o $x > 5$» se niega como $0 \le x \le 5$.|「$x < 0$ または $x > 5$」の否定は $0 \le x \le 5$。|“$x < 0$ 或 $x > 5$”的否定是 $0 \le x \le 5$。`,
      a: [F(R`\lnot(x < 0 \lor x > 5)`), Y(R`\equiv x \ge 0 \land x \le 5`)] },
    { s: TRY_TF, a: [F(R`p\ \text{false},\quad q\ \text{true}`)],
      ex: { k: 'val', v: '0', q: R`$p$ is false and $q$ is true. Is $\lnot(p \lor q)$ true (1) or false (0)?|$p$ est fausse et $q$ vraie. $\lnot(p \lor q)$ est-elle vraie (1) ou fausse (0) ?|$p$ es falsa y $q$ verdadera. ¿$\lnot(p \lor q)$ es verdadera (1) o falsa (0)?|$p$ 偽、$q$ 真。$\lnot(p \lor q)$ は真 (1) か偽 (0) か。|$p$ 假、$q$ 真，$\lnot(p \lor q)$ 为真 (1) 还是假 (0)？`, sol: [R`p \lor q\ \text{is true}`, R`\lnot(p \lor q)\ \text{is false: } 0`] } });

  lesson('Propositions/Implication', 'The implication|L’implication|La implicación|含意（ならば）|蕴含',
    { s: R`“If $p$ then $q$” only fails when $p$ happens and $q$ does not. So it means the same as “not $p$, or $q$”, and its negation is “$p$ and not $q$” — a counterexample. The negation of an implication is never another implication.|« Si $p$ alors $q$ » n’échoue que si $p$ se produit sans $q$. Elle équivaut donc à « non $p$ ou $q$ », et sa négation est « $p$ et non $q$ » — un contre-exemple. La négation d’une implication n’est jamais une implication.|«Si $p$ entonces $q$» solo falla cuando ocurre $p$ y no $q$. Equivale a «no $p$, o $q$», y su negación es «$p$ y no $q$»: un contraejemplo. La negación de una implicación nunca es otra implicación.|「$p$ ならば $q$」が偽になるのは $p$ が起きて $q$ が起きないときだけ。よって「$p$ でない、または $q$」と同値で、否定は「$p$ かつ $q$ でない」（反例）。|“若 $p$ 则 $q$”只在 $p$ 发生而 $q$ 不发生时失败。所以等价于“非 $p$ 或 $q$”，其否定是“$p$ 且非 $q$”——一个反例。蕴含的否定永远不是蕴含。`,
      a: [Y(R`p \Rightarrow q \equiv \lnot p \lor q`), Y(R`\lnot(p \Rightarrow q) \equiv p \land \lnot q`)] },
    { s: R`“If $n$ is prime, then $n$ is odd” is false because of $n = 2$: prime and not odd — exactly $p \land \lnot q$.|« Si $n$ est premier, alors $n$ est impair » est faux à cause de $n = 2$ : premier et pas impair.|«Si $n$ es primo, $n$ es impar» es falsa por $n = 2$: primo y no impar.|$n = 2$ が反例。|$n = 2$ 是反例。`,
      a: [F(R`n = 2:\ \text{prime} \land \lnot\text{odd}`), Y(R`\Rightarrow\ \text{the implication is false}`)] },
    { a: [F(R`p \Rightarrow q`)],
      ex: { k: 'val', v: '1', q: R`In how many of the four rows of the truth table is $p \Rightarrow q$ false?|Dans combien des quatre lignes de la table de vérité $p \Rightarrow q$ est-elle fausse ?|¿En cuántas de las cuatro filas de la tabla de verdad es falsa $p \Rightarrow q$?|真理値表の 4 行のうち $p \Rightarrow q$ が偽となる行は何行か。|真值表的四行中 $p \Rightarrow q$ 为假的有几行？`, sol: [R`\text{false only for } p = \text{T},\ q = \text{F}`, R`1`] } });

  lesson('Propositions/Converse, inverse, contrapositive', 'Converse, inverse and contrapositive|Réciproque, contraire et contraposée|Recíproca, contraria y contrarrecíproca|逆・裏・対偶|逆命题、否命题、逆否命题',
    { s: R`From $p \Rightarrow q$ you can build three statements. The contrapositive $\lnot q \Rightarrow \lnot p$ always has the same truth value as the original. The converse $q \Rightarrow p$ and the inverse $\lnot p \Rightarrow \lnot q$ agree with each other, but not necessarily with the original.|À partir de $p \Rightarrow q$ on forme trois énoncés. La contraposée $\lnot q \Rightarrow \lnot p$ a toujours la même valeur que l’original. La réciproque $q \Rightarrow p$ et la contraire $\lnot p \Rightarrow \lnot q$ ont la même valeur entre elles, mais pas forcément celle de l’original.|A partir de $p \Rightarrow q$ se forman tres enunciados. La contrarrecíproca $\lnot q \Rightarrow \lnot p$ siempre tiene el mismo valor que la original. La recíproca $q \Rightarrow p$ y la contraria $\lnot p \Rightarrow \lnot q$ coinciden entre sí, pero no necesariamente con la original.|$p \Rightarrow q$ から 3 つの命題ができる。対偶 $\lnot q \Rightarrow \lnot p$ は常に元と同じ真偽。逆 $q \Rightarrow p$ と裏 $\lnot p \Rightarrow \lnot q$ は互いに同じだが、元と同じとは限らない。|由 $p \Rightarrow q$ 可构成三个命题。逆否命题 $\lnot q \Rightarrow \lnot p$ 总与原命题同真假。逆命题 $q \Rightarrow p$ 与否命题 $\lnot p \Rightarrow \lnot q$ 彼此同真假，但不一定与原命题相同。`,
      a: [F(R`\text{converse: } q \Rightarrow p,\quad \text{inverse: } \lnot p \Rightarrow \lnot q`, { s: 22 }), Y(R`\text{contrapositive: } \lnot q \Rightarrow \lnot p \ \equiv\ p \Rightarrow q`, { s: 22 })] },
    { s: R`“If it rains, the street is wet” (true). Contrapositive: “if the street is dry, it is not raining” (true). Converse: “if the street is wet, it rains” (false — someone may have washed it).|« S’il pleut, la rue est mouillée » (vrai). Contraposée : « si la rue est sèche, il ne pleut pas » (vrai). Réciproque : « si la rue est mouillée, il pleut » (faux).|«Si llueve, la calle está mojada» (verdadero). Contrarrecíproca: «si la calle está seca, no llueve» (verdadero). Recíproca: «si la calle está mojada, llueve» (falso).|対偶は真、逆は偽。|逆否命题真，逆命题假。`,
      a: [F(R`\text{rain} \Rightarrow \text{wet}\ \checkmark`), Y(R`\text{dry} \Rightarrow \text{no rain}\ \checkmark,\quad \text{wet} \Rightarrow \text{rain}\ \times`, { s: 22 })] },
    { a: [F(R`x = 2 \Rightarrow x^2 = 4`)],
      ex: { k: 'val', v: '1', q: R`For “if $x = 2$ then $x^2 = 4$”, how many of its converse, inverse and contrapositive are true?|Pour « si $x = 2$ alors $x^2 = 4$ », combien parmi la réciproque, la contraire et la contraposée sont vraies ?|Para «si $x = 2$ entonces $x^2 = 4$», ¿cuántas de su recíproca, contraria y contrarrecíproca son verdaderas?|「$x = 2$ ならば $x^2 = 4$」の逆・裏・対偶のうち真はいくつか。|“若 $x = 2$ 则 $x^2 = 4$”的逆命题、否命题、逆否命题中有几个为真？`, sol: [R`\text{converse: } x^2 = 4 \Rightarrow x = 2\ \times\ (x = -2)`, R`\text{inverse } \times,\ \text{contrapositive } \checkmark`, R`1`] } });

  // =============================== Necessary and sufficient ===============================
  lesson('Necessary and sufficient/Sufficient condition', 'Sufficient and necessary conditions|Conditions suffisante et nécessaire|Condiciones suficiente y necesaria|十分条件と必要条件|充分条件与必要条件',
    { s: R`If $p \Rightarrow q$, then knowing $p$ is enough to guarantee $q$: $p$ is sufficient for $q$. And $q$ is necessary for $p$: without $q$, $p$ cannot happen. The arrow points from the sufficient condition to the necessary one.|Si $p \Rightarrow q$, savoir $p$ suffit à garantir $q$ : $p$ est suffisante pour $q$. Et $q$ est nécessaire pour $p$ : sans $q$, $p$ ne peut pas avoir lieu. La flèche va de la condition suffisante vers la condition nécessaire.|Si $p \Rightarrow q$, saber $p$ basta para garantizar $q$: $p$ es suficiente para $q$. Y $q$ es necesaria para $p$: sin $q$, $p$ no puede darse. La flecha va de la condición suficiente a la necesaria.|$p \Rightarrow q$ なら $p$ がわかれば $q$ が保証される：$p$ は $q$ の十分条件。$q$ は $p$ の必要条件（$q$ なしに $p$ は起こらない）。矢印は十分条件から必要条件へ。|若 $p \Rightarrow q$，知道 $p$ 就足以保证 $q$：$p$ 是 $q$ 的充分条件；$q$ 是 $p$ 的必要条件：没有 $q$，$p$ 不可能发生。箭头从充分条件指向必要条件。`,
      a: [Y(R`p \Rightarrow q:\ p\ \text{sufficient},\ q\ \text{necessary}`, { s: 24 })] },
    { s: R`$x = 3 \Rightarrow x^2 = 9$: being 3 is sufficient for having square 9, but not necessary ($-3$ also works). Having square 9 is necessary for being 3.|$x = 3 \Rightarrow x^2 = 9$ : être 3 suffit, mais n’est pas nécessaire ($-3$ marche aussi).|$x = 3 \Rightarrow x^2 = 9$: ser 3 es suficiente, pero no necesario ($-3$ también vale).|$x = 3$ は十分条件だが必要条件ではない。|$x = 3$ 是充分不必要条件。`,
      a: [Y(R`x = 3 \Rightarrow x^2 = 9,\qquad x^2 = 9 \not\Rightarrow x = 3`, { s: 24 })] },
    { s: TRY_TF, a: [F(R`x > 5\ \ ?\ \ x > 3`)],
      ex: { k: 'val', v: '1', q: R`Is “$x > 5$” a sufficient condition for “$x > 3$”? Type 1 (yes) or 0 (no).|« $x > 5$ » est-elle une condition suffisante pour « $x > 3$ » ? Tapez 1 (oui) ou 0 (non).|¿Es «$x > 5$» condición suficiente para «$x > 3$»? Escribe 1 (sí) o 0 (no).|「$x > 5$」は「$x > 3$」の十分条件か。1（はい）か 0（いいえ）。|“$x > 5$”是“$x > 3$”的充分条件吗？输入 1（是）或 0（否）。`, sol: [R`x > 5 \Rightarrow x > 3`, R`\text{yes: } 1`] } });

  lesson('Necessary and sufficient/With sets', 'Conditions as sets|Conditions et ensembles|Condiciones como conjuntos|条件と集合|条件与集合',
    { s: R`Let $P$ and $Q$ be the sets of values where $p$ and $q$ are true. “$p \Rightarrow q$” says every point of $P$ is in $Q$: $P \subseteq Q$. The smaller set gives the sufficient condition, the larger the necessary one.|Soient $P$ et $Q$ les ensembles où $p$ et $q$ sont vraies. « $p \Rightarrow q$ » dit que tout point de $P$ est dans $Q$ : $P \subseteq Q$. Le plus petit ensemble donne la condition suffisante, le plus grand la condition nécessaire.|Sean $P$ y $Q$ los conjuntos donde $p$ y $q$ son verdaderas. «$p \Rightarrow q$» dice que todo punto de $P$ está en $Q$: $P \subseteq Q$. El conjunto menor da la condición suficiente y el mayor la necesaria.|$p$, $q$ が真となる集合を $P$, $Q$ とすると「$p \Rightarrow q$」は $P \subseteq Q$。小さい集合が十分条件、大きい集合が必要条件。|设 $P$、$Q$ 为使 $p$、$q$ 为真的集合。“$p \Rightarrow q$”即 $P$ 的每点都在 $Q$ 中：$P \subseteq Q$。小集合给出充分条件，大集合给出必要条件。`,
      a: [Y(R`p \Rightarrow q \iff P \subseteq Q`, { s: 30 }), ...LINE([[0, 3]], [[0, false, '0'], [3, false, '3']], [1.5, 0], 2.8), SG([1, 0.35], [2, 0.35], 'p', { w: 5, d: 900 })] },
    { s: R`$p$: $1 < x < 2$, $q$: $0 < x < 3$. Since $(1, 2) \subseteq (0, 3)$ (pink inside yellow), $p \Rightarrow q$: $p$ is sufficient, $q$ is necessary.|$p$ : $1 < x < 2$, $q$ : $0 < x < 3$. Comme $(1, 2) \subseteq (0, 3)$, $p \Rightarrow q$.|$p$: $1 < x < 2$, $q$: $0 < x < 3$. Como $(1, 2) \subseteq (0, 3)$, $p \Rightarrow q$.|$(1, 2) \subseteq (0, 3)$ なので $p \Rightarrow q$。|$(1, 2) \subseteq (0, 3)$，故 $p \Rightarrow q$。`,
      a: [Y(R`(1, 2) \subseteq (0, 3) \Rightarrow p \Rightarrow q`)] },
    { a: [F(R`p:\ 0 \le x \le a,\qquad q:\ 0 \le x \le 5`)],
      ex: { k: 'val', v: '5', q: R`$p$: $0 \le x \le a$ (with $a > 0$), $q$: $0 \le x \le 5$. What is the largest $a$ for which $p$ is sufficient for $q$?|$p$ : $0 \le x \le a$ ($a > 0$), $q$ : $0 \le x \le 5$. Quel est le plus grand $a$ pour lequel $p$ est suffisante pour $q$ ?|$p$: $0 \le x \le a$ ($a > 0$), $q$: $0 \le x \le 5$. ¿Cuál es el mayor $a$ para el que $p$ es suficiente para $q$?|$p$: $0 \le x \le a$、$q$: $0 \le x \le 5$。$p$ が $q$ の十分条件となる最大の $a$ は？|$p$：$0 \le x \le a$，$q$：$0 \le x \le 5$，使 $p$ 为 $q$ 充分条件的最大 $a$ 是多少？`, sol: [R`[0, a] \subseteq [0, 5]`, R`a \le 5 \Rightarrow a = 5`] } });

  lesson('Necessary and sufficient/Necessary and sufficient', 'Necessary and sufficient|Condition nécessaire et suffisante|Condición necesaria y suficiente|必要十分条件|充要条件',
    { s: R`When the implication goes both ways, $p$ and $q$ are true for exactly the same values: $P = Q$. Then each can replace the other — that is what “if and only if” means, and what solving an equation by equivalent steps relies on.|Quand l’implication va dans les deux sens, $p$ et $q$ sont vraies pour exactement les mêmes valeurs : $P = Q$. Chacune peut remplacer l’autre — c’est le sens de « si et seulement si », et ce sur quoi repose la résolution d’une équation par équivalences.|Cuando la implicación va en los dos sentidos, $p$ y $q$ son verdaderas para exactamente los mismos valores: $P = Q$. Cada una puede sustituir a la otra; eso significa «si y solo si», y en ello se basa resolver una ecuación por pasos equivalentes.|含意が両方向なら $p$ と $q$ は全く同じ値で真：$P = Q$。互いに置き換えられる（「〜のとき、かつそのときに限り」）。同値変形で方程式を解くのはこれに基づく。|蕴含双向成立时，$p$ 与 $q$ 在完全相同的值上为真：$P = Q$。二者可互相替换——这就是“当且仅当”，用等价变形解方程正依赖于此。`,
      a: [Y(R`p \iff q \iff P = Q`, { s: 30 })] },
    { s: R`$x^2 = 4 \iff x = 2 \lor x = -2$. But $x = 2$ alone is only sufficient: the step “$x^2 = 4$, so $x = 2$” loses a solution.|$x^2 = 4 \iff x = 2$ ou $x = -2$. Mais $x = 2$ seul n’est que suffisant : écrire « $x^2 = 4$ donc $x = 2$ » perd une solution.|$x^2 = 4 \iff x = 2 \lor x = -2$. Pero $x = 2$ sola solo es suficiente: «$x^2 = 4$, luego $x = 2$» pierde una solución.|$x^2 = 4 \iff x = \pm 2$。|$x^2 = 4 \iff x = \pm 2$。`,
      a: [Y(R`x^2 = 4 \iff x = \pm 2`)] },
    { a: [F(R`x > k\ \iff\ x + 3 > 5`)],
      ex: { k: 'val', v: '2', q: R`For which $k$ is “$x > k$” a necessary and sufficient condition for “$x + 3 > 5$”?|Pour quel $k$ « $x > k$ » est-elle une condition nécessaire et suffisante pour « $x + 3 > 5$ » ?|¿Para qué $k$ es «$x > k$» condición necesaria y suficiente para «$x + 3 > 5$»?|「$x > k$」が「$x + 3 > 5$」の必要十分条件となる $k$ は？|$k$ 为何值时“$x > k$”是“$x + 3 > 5$”的充要条件？`, sol: [R`x + 3 > 5 \iff x > 2`, R`k = 2`] } });

  // =============================== Quantifiers ===============================
  lesson('Quantifiers/For all, there exists', 'For all, there exists|Pour tout, il existe|Para todo, existe|すべての、ある|任意、存在',
    { s: R`“$\forall x$” claims something for every $x$ of the set — one failure makes it false. “$\exists\,x$” claims at least one $x$ works — one example makes it true. The set matters: $\exists\,x: x^2 = 2$ is true in $\mathbb R$ but false in $\mathbb Q$.|« $\forall x$ » affirme une chose pour tous les $x$ de l’ensemble — un seul échec la rend fausse. « $\exists\,x$ » affirme qu’au moins un $x$ convient — un exemple suffit. L’ensemble compte : $\exists\,x : x^2 = 2$ est vraie dans $\mathbb R$, fausse dans $\mathbb Q$.|«$\forall x$» afirma algo para todo $x$ del conjunto: un fallo la hace falsa. «$\exists\,x$» afirma que al menos un $x$ sirve: un ejemplo basta. El conjunto importa: $\exists\,x: x^2 = 2$ es verdadera en $\mathbb R$ y falsa en $\mathbb Q$.|「$\forall x$」は集合のすべての $x$ についての主張（1 つの例外で偽）。「$\exists\,x$」は少なくとも 1 つあるという主張（1 例で真）。集合が大事：$x^2 = 2$ となる $x$ は $\mathbb R$ にはあるが $\mathbb Q$ にはない。|“$\forall x$”断言集合中每个 $x$ 都满足——一个反例就为假。“$\exists\,x$”断言至少一个 $x$ 满足——一个例子就为真。集合很重要：$\exists\,x: x^2 = 2$ 在 $\mathbb R$ 中真，在 $\mathbb Q$ 中假。`,
      a: [Y(R`\forall x \in A:\ p(x),\qquad \exists\,x \in A:\ p(x)`), F(R`\forall x \in \mathbb R:\ x^2 \ge 0\ \checkmark`)] },
    { s: R`“$\forall n \in \mathbb N$: $n^2 \ge n$” is true. “$\forall x \in \mathbb R$: $x^2 \ge x$” is false: $x = \tfrac12$ gives $\tfrac14 < \tfrac12$.|« $\forall n \in \mathbb N$ : $n^2 \ge n$ » est vraie. « $\forall x \in \mathbb R$ : $x^2 \ge x$ » est fausse : $x = \tfrac12$.|«$\forall n \in \mathbb N$: $n^2 \ge n$» es verdadera. «$\forall x \in \mathbb R$: $x^2 \ge x$» es falsa: $x = \tfrac12$.|$x = \tfrac12$ が反例。|$x = \tfrac12$ 是反例。`,
      a: [F(R`\forall n \in \mathbb N:\ n^2 \ge n\ \checkmark`), Y(R`x = \tfrac12:\ \tfrac14 < \tfrac12\ \Rightarrow\ \forall x \in \mathbb R\ \times`, { s: 24 })] },
    { a: [F(R`A = \{-2, -1, 0, 1, 2\},\quad p(x):\ x^2 < 2`)],
      ex: { k: 'val', v: '3', q: R`$A = \{-2, -1, 0, 1, 2\}$. For how many $x \in A$ is $x^2 < 2$ true? (So is $\forall x \in A: x^2 < 2$ true?)|$A = \{-2, -1, 0, 1, 2\}$. Pour combien de $x \in A$ a-t-on $x^2 < 2$ ?|$A = \{-2, -1, 0, 1, 2\}$. ¿Para cuántos $x \in A$ se cumple $x^2 < 2$?|$A = \{-2, -1, 0, 1, 2\}$ のうち $x^2 < 2$ を満たす $x$ は何個か。|$A = \{-2, -1, 0, 1, 2\}$ 中满足 $x^2 < 2$ 的 $x$ 有几个？`, sol: [R`-1,\ 0,\ 1`, R`3\ (\text{so } \forall\ \text{is false})`] } });

  lesson('Quantifiers/Negating quantifiers', 'Negating quantifiers|Négation des quantificateurs|Negación de cuantificadores|量化子の否定|量词的否定',
    { s: R`“Not every $x$ works” means some $x$ fails; “no $x$ works” means every $x$ fails. Negating swaps $\forall$ and $\exists$ and negates the property — keep the set the same.|« Tous les $x$ ne conviennent pas » signifie qu’un $x$ échoue ; « aucun $x$ ne convient » signifie que tous échouent. La négation échange $\forall$ et $\exists$ et nie la propriété — l’ensemble reste le même.|«No todo $x$ sirve» significa que algún $x$ falla; «ningún $x$ sirve» significa que todos fallan. Negar intercambia $\forall$ y $\exists$ y niega la propiedad; el conjunto no cambia.|「すべての $x$ で成り立つ、わけではない」は「成り立たない $x$ がある」。否定で $\forall$ と $\exists$ が入れ替わり、性質も否定（集合は同じ）。|“并非所有 $x$ 都满足”即存在 $x$ 不满足；“没有 $x$ 满足”即所有 $x$ 都不满足。否定交换 $\forall$ 与 $\exists$ 并否定性质——集合不变。`,
      a: [Y(R`\lnot(\forall x:\ p) \equiv \exists\,x:\ \lnot p`), Y(R`\lnot(\exists\,x:\ p) \equiv \forall x:\ \lnot p`)] },
    { s: R`Negate “every student passed”: “some student did not pass” (not “no student passed”). Negate “$\exists\,x \in \mathbb R$: $x^2 < 0$”: “$\forall x \in \mathbb R$: $x^2 \ge 0$”.|Nier « tous les élèves ont réussi » : « un élève au moins a échoué » (et non « aucun n’a réussi »).|Negar «todos aprobaron»: «algún alumno no aprobó» (no «nadie aprobó»).|「全員合格」の否定は「合格しなかった人がいる」。|“都通过了”的否定是“有人没通过”。`,
      a: [F(R`\lnot(\forall s:\ \text{passed}) \equiv \exists\,s:\ \text{failed}`), Y(R`\lnot(\exists\,x:\ x^2 < 0) \equiv \forall x:\ x^2 \ge 0`)] },
    { s: TRY_TF, a: [F(R`\lnot\big(\forall n \in \mathbb N:\ n^2 \ge n\big)`)],
      ex: { k: 'val', v: '0', q: R`Is the statement $\lnot\big(\forall n \in \mathbb N:\ n^2 \ge n\big)$ true (1) or false (0)?|La proposition $\lnot\big(\forall n \in \mathbb N :\ n^2 \ge n\big)$ est-elle vraie (1) ou fausse (0) ?|¿La proposición $\lnot\big(\forall n \in \mathbb N:\ n^2 \ge n\big)$ es verdadera (1) o falsa (0)?|$\lnot\big(\forall n \in \mathbb N:\ n^2 \ge n\big)$ は真 (1) か偽 (0) か。|$\lnot\big(\forall n \in \mathbb N:\ n^2 \ge n\big)$ 为真 (1) 还是假 (0)？`, sol: [R`\equiv \exists\,n:\ n^2 < n`, R`\text{no such } n \in \mathbb N:\ 0`] } });

  lesson('Quantifiers/Unique existence', 'Unique existence|Existence et unicité|Existencia y unicidad|ただ一つ存在する|存在唯一',
    { s: R`“$\exists!\,x$” says two things: there is an $x$ (existence) and there are no two different ones (uniqueness). To prove uniqueness, suppose $x_1$ and $x_2$ both work and show $x_1 = x_2$.|« $\exists!\,x$ » dit deux choses : il existe un $x$ (existence) et il n’y en a pas deux différents (unicité). Pour l’unicité, on suppose que $x_1$ et $x_2$ conviennent et on montre $x_1 = x_2$.|«$\exists!\,x$» dice dos cosas: hay un $x$ (existencia) y no hay dos distintos (unicidad). Para la unicidad, supón que $x_1$ y $x_2$ sirven y demuestra $x_1 = x_2$.|「$\exists!\,x$」は存在と一意性の 2 つの主張。一意性は $x_1$, $x_2$ がともに満たすと仮定して $x_1 = x_2$ を示す。|“$\exists!\,x$”包含两点：存在 $x$（存在性），且没有两个不同的（唯一性）。证明唯一性：设 $x_1$、$x_2$ 都满足，证 $x_1 = x_2$。`,
      a: [Y(R`\exists!\,x:\ p(x)`, { s: 30 }), F(R`p(x_1) \land p(x_2) \Rightarrow x_1 = x_2`)] },
    { s: R`$2x + 1 = 7$ has the unique solution $x = 3$: if $2x_1 + 1 = 2x_2 + 1$ then $x_1 = x_2$. But $x^2 = 9$ has two, so “$\exists!\,x$: $x^2 = 9$” is false.|$2x + 1 = 7$ a l’unique solution $x = 3$. Mais $x^2 = 9$ en a deux.|$2x + 1 = 7$ tiene la única solución $x = 3$. Pero $x^2 = 9$ tiene dos.|$x = 3$ はただ一つ。$x^2 = 9$ は 2 つ。|$x = 3$ 唯一；$x^2 = 9$ 有两个。`,
      a: [F(R`\exists!\,x:\ 2x + 1 = 7\quad (x = 3)`), Y(R`x^2 = 9:\ x = \pm 3\ \Rightarrow\ \lnot\exists!`)] },
    { a: [F(R`x \in \mathbb R:\ x^3 = 8`)],
      ex: { k: 'val', v: '2', q: R`$x^3 = 8$ has exactly one real solution. Find it.|$x^3 = 8$ a exactement une solution réelle. Trouvez-la.|$x^3 = 8$ tiene exactamente una solución real. Hállala.|$x^3 = 8$ はただ一つの実数解をもつ。求めよ。|$x^3 = 8$ 恰有一个实数解，求它。`, sol: [R`x^3\ \text{is increasing: at most one}`, R`x = 2`] } });

  // =============================== Methods of proof ===============================
  lesson('Methods of proof/Mathematical induction', 'Mathematical induction|Récurrence|Inducción matemática|数学的帰納法|数学归纳法',
    { s: R`Like dominoes: show the first one falls ($P(1)$), and that each falling domino knocks over the next ($P(k) \Rightarrow P(k + 1)$). Then all fall. In the step you may use $P(k)$ — that is the whole point.|Comme des dominos : on montre que le premier tombe ($P(1)$), puis que chaque domino qui tombe fait tomber le suivant ($P(k) \Rightarrow P(k + 1)$). Alors tous tombent. Dans l’hérédité on a le droit d’utiliser $P(k)$ — c’est tout l’intérêt.|Como fichas de dominó: demuestra que cae la primera ($P(1)$) y que cada ficha que cae tira la siguiente ($P(k) \Rightarrow P(k + 1)$). Entonces caen todas. En el paso puedes usar $P(k)$: esa es la clave.|ドミノ倒しのように、最初が倒れる（$P(1)$）こと、倒れたものが次を倒す（$P(k) \Rightarrow P(k + 1)$）ことを示せば全部倒れる。後半では $P(k)$ を使ってよい。|像多米诺骨牌：证第一块倒下（$P(1)$），且每块倒下推倒下一块（$P(k) \Rightarrow P(k + 1)$），则全部倒下。归纳步骤中可以用 $P(k)$——这正是关键。`,
      a: [Y(R`P(1) \land \big(P(k) \Rightarrow P(k + 1)\big) \Rightarrow \forall n:\ P(n)`, { s: 22 }), S2([3, 0.6], 3.6), ...SEQ([0, 1, 2, 3, 4, 5].map(i => ['poly3', [Z(i, 0), Z(i + 0.25, 0), Z(i + 0.25 + (i < 3 ? 0.9 : 0), 1.4 - (i < 3 ? 0.3 : 0)), Z(i + (i < 3 ? 0.9 : 0), 1.4 - (i < 3 ? 0.3 : 0))], { c: i < 3 ? 'y' : 'b', fill: 0.35 }]), 200, 200)] },
    { s: R`$1 + 2 + \dots + n = \tfrac{n(n + 1)}{2}$. Base: $1 = \tfrac{1\cdot 2}{2}$. Step: $\tfrac{k(k + 1)}{2} + (k + 1) = \tfrac{(k + 1)(k + 2)}{2}$ — the formula for $k + 1$.|Initialisation : $1 = \tfrac{1\cdot 2}{2}$. Hérédité : $\tfrac{k(k + 1)}{2} + (k + 1) = \tfrac{(k + 1)(k + 2)}{2}$.|Base: $1 = \tfrac{1\cdot 2}{2}$. Paso: $\tfrac{k(k + 1)}{2} + (k + 1) = \tfrac{(k + 1)(k + 2)}{2}$.|基底と帰納段階。|奠基与归纳。`,
      a: [F(R`n = 1:\ 1 = \tfrac{1\cdot 2}{2}\ \checkmark`), Y(R`\frac{k(k + 1)}{2} + (k + 1) = \frac{(k + 1)(k + 2)}{2}`)] },
    { a: [F(R`1 + 3 + 5 + \dots + (2n - 1) = n^2`)],
      ex: { k: 'val', v: '100', q: R`By induction one proves $1 + 3 + \dots + (2n - 1) = n^2$. Use it to compute $1 + 3 + 5 + \dots + 19$.|Par récurrence, $1 + 3 + \dots + (2n - 1) = n^2$. Calculez $1 + 3 + 5 + \dots + 19$.|Por inducción, $1 + 3 + \dots + (2n - 1) = n^2$. Calcula $1 + 3 + 5 + \dots + 19$.|帰納法で $1 + 3 + \dots + (2n - 1) = n^2$。$1 + 3 + 5 + \dots + 19$ を求めよ。|由归纳法 $1 + 3 + \dots + (2n - 1) = n^2$，求 $1 + 3 + 5 + \dots + 19$。`, sol: [R`2n - 1 = 19 \Rightarrow n = 10`, R`10^2 = 100`] } });

  lesson('Methods of proof/Contradiction', 'Proof by contradiction|Raisonnement par l’absurde|Reducción al absurdo|背理法|反证法',
    { s: R`Assume the opposite of what you want to prove and reason until you reach something impossible ($\bot$). Since correct reasoning cannot lead from a truth to an impossibility, the assumption was false — so the statement is true.|On suppose le contraire de ce qu’on veut montrer et on raisonne jusqu’à une impossibilité ($\bot$). Un raisonnement correct ne mène pas d’une vérité à une absurdité : l’hypothèse était fausse, donc l’énoncé est vrai.|Supón lo contrario de lo que quieres demostrar y razona hasta llegar a algo imposible ($\bot$). Un razonamiento correcto no lleva de una verdad a un imposible, así que la suposición era falsa y el enunciado es verdadero.|示したいことの否定を仮定し、矛盾（$\bot$）が出るまで推論する。正しい推論で真から矛盾は出ないので、仮定が偽、すなわち命題は真。|假设要证命题的反面，推理直到得出不可能（$\bot$）。正确推理不会从真导出矛盾，所以假设为假——命题为真。`,
      a: [Y(R`\lnot p \Rightarrow \bot\ \ \therefore\ p`, { s: 30 })] },
    { s: R`$\sqrt2$ is irrational. Suppose $\sqrt2 = \tfrac ab$ in lowest terms. Then $a^2 = 2b^2$, so $a$ is even, $a = 2k$; then $b^2 = 2k^2$, so $b$ is even too — but the fraction was in lowest terms. Contradiction.|$\sqrt2$ est irrationnel. Supposons $\sqrt2 = \tfrac ab$ irréductible. Alors $a^2 = 2b^2$, $a$ est pair, $a = 2k$ ; puis $b^2 = 2k^2$, $b$ est pair — contradiction.|$\sqrt2$ es irracional. Supón $\sqrt2 = \tfrac ab$ irreducible. Entonces $a^2 = 2b^2$, $a$ es par, $a = 2k$; luego $b^2 = 2k^2$ y $b$ también es par: contradicción.|$a$, $b$ ともに偶数となり既約に矛盾。|$a$、$b$ 都为偶数，与最简矛盾。`,
      a: [F(R`\sqrt2 = \frac ab \Rightarrow a^2 = 2b^2 \Rightarrow a = 2k`), Y(R`4k^2 = 2b^2 \Rightarrow b^2 = 2k^2\ \Rightarrow\ \bot`)] },
    { a: [F(R`a^2 = 2b^2,\quad a = 2k`)],
      ex: { k: 'val', v: '2', q: R`In the proof above, $a^2 = 2b^2$ and $a = 2k$. Then $b^2 = c\,k^2$. Find $c$.|Dans la preuve ci-dessus, $a^2 = 2b^2$ et $a = 2k$. Alors $b^2 = c\,k^2$. Trouvez $c$.|En la demostración anterior, $a^2 = 2b^2$ y $a = 2k$. Entonces $b^2 = c\,k^2$. Halla $c$.|$a^2 = 2b^2$, $a = 2k$ のとき $b^2 = c\,k^2$。$c$ を求めよ。|$a^2 = 2b^2$，$a = 2k$，则 $b^2 = c\,k^2$，求 $c$。`, sol: [R`4k^2 = 2b^2`, R`b^2 = 2k^2:\ c = 2`] } });

  lesson('Methods of proof/Contrapositive', 'Proof by contrapositive|Preuve par contraposée|Demostración por contrarrecíproco|対偶による証明|逆否证明',
    { s: R`Instead of $p \Rightarrow q$, prove the equivalent $\lnot q \Rightarrow \lnot p$. It helps when “not $q$” gives you something concrete to work with — e.g. “$n$ odd” gives $n = 2k + 1$.|Au lieu de $p \Rightarrow q$, on prouve l’équivalent $\lnot q \Rightarrow \lnot p$. Utile quand « non $q$ » fournit quelque chose de concret — par ex. « $n$ impair » donne $n = 2k + 1$.|En lugar de $p \Rightarrow q$ demuestra el equivalente $\lnot q \Rightarrow \lnot p$. Ayuda cuando «no $q$» da algo concreto con qué trabajar: «$n$ impar» da $n = 2k + 1$.|$p \Rightarrow q$ の代わりに同値な $\lnot q \Rightarrow \lnot p$ を示す。「$q$ でない」が具体的な形（$n$ 奇数なら $n = 2k + 1$）をくれるときに便利。|不证 $p \Rightarrow q$，而证等价的 $\lnot q \Rightarrow \lnot p$。当“非 $q$”给出具体形式时很有用——如“$n$ 为奇数”给出 $n = 2k + 1$。`,
      a: [Y(R`\lnot q \Rightarrow \lnot p\ \ \therefore\ p \Rightarrow q`, { s: 30 })] },
    { s: R`“If $n^2$ is even then $n$ is even.” Contrapositive: if $n$ is odd, $n = 2k + 1$, then $n^2 = 4k^2 + 4k + 1 = 2(2k^2 + 2k) + 1$ is odd. Done.|« Si $n^2$ est pair, alors $n$ est pair. » Contraposée : si $n = 2k + 1$, alors $n^2 = 2(2k^2 + 2k) + 1$ est impair.|«Si $n^2$ es par, $n$ es par.» Contrarrecíproco: si $n = 2k + 1$, $n^2 = 2(2k^2 + 2k) + 1$ es impar.|対偶：$n = 2k + 1$ なら $n^2$ は奇数。|逆否：$n = 2k + 1$ 则 $n^2$ 为奇数。`,
      a: [F(R`n = 2k + 1`), Y(R`n^2 = 2(2k^2 + 2k) + 1\ \text{odd}`)] },
    { s: 'Type an expression in x and check it.|Tapez une expression en x et vérifiez.|Escribe una expresión en x y compruébala.|x の式を入力して確かめよう。|输入关于 x 的式子并检查。', a: [F(R`n = 2x + 1`)],
      ex: { k: 'expr', f: '2x^2+2x', q: R`Write $(2x + 1)^2 = 2m + 1$. Give $m$ as an expression in $x$.|Écrivez $(2x + 1)^2 = 2m + 1$. Donnez $m$ en fonction de $x$.|Escribe $(2x + 1)^2 = 2m + 1$. Da $m$ en función de $x$.|$(2x + 1)^2 = 2m + 1$ と書くとき $m$ を $x$ の式で表せ。|写成 $(2x + 1)^2 = 2m + 1$，用 $x$ 表示 $m$。`, sol: [R`(2x + 1)^2 = 4x^2 + 4x + 1`, R`m = 2x^2 + 2x`] } });

  lesson('Methods of proof/Counterexample', 'Counterexamples|Contre-exemples|Contraejemplos|反例|反例',
    { s: R`A “for all” statement is destroyed by a single case where it fails. No number of examples can prove it, but one counterexample disproves it. Look at small, extreme or special values first.|Une proposition « pour tout » est détruite par un seul cas où elle échoue. Aucun nombre d’exemples ne la prouve, mais un seul contre-exemple la réfute. Essayez d’abord des valeurs petites, extrêmes ou particulières.|Un enunciado «para todo» se destruye con un único caso en que falla. Ningún número de ejemplos lo demuestra, pero un contraejemplo lo refuta. Prueba primero valores pequeños, extremos o especiales.|「すべての」主張は 1 つの例外で崩れる。例をいくつ挙げても証明にならないが、反例 1 つで否定できる。小さい値、極端な値、特別な値から試そう。|“对所有”命题只要一个失败的例子就被推翻。再多的例子也不能证明，但一个反例就能否定。先试小的、极端的或特殊的值。`,
      a: [Y(R`\exists\,x:\ \lnot p(x)\ \Rightarrow\ \lnot\big(\forall x:\ p(x)\big)`, { s: 24 })] },
    { s: R`“$n^2 + n + 41$ is prime for every $n$” holds for $n = 0, \dots, 39$, yet $n = 40$ gives $1681 = 41^2$. Forty examples did not prove it; one value disproved it.|« $n^2 + n + 41$ est toujours premier » marche pour $n = 0, \dots, 39$, mais $n = 40$ donne $1681 = 41^2$.|«$n^2 + n + 41$ siempre es primo» vale para $n = 0, \dots, 39$, pero $n = 40$ da $1681 = 41^2$.|$n = 40$ で $41^2$。|$n = 40$ 时为 $41^2$。`,
      a: [F(R`n = 0, \dots, 39:\ \text{prime}`), Y(R`n = 40:\ 1681 = 41^2`)] },
    { a: [F(R`n^2 - n + 11\ \text{prime for all } n \ge 1\ ?`)],
      ex: { k: 'val', v: '11', q: R`Find the smallest $n \ge 1$ for which $n^2 - n + 11$ is not prime.|Trouvez le plus petit $n \ge 1$ pour lequel $n^2 - n + 11$ n’est pas premier.|Halla el menor $n \ge 1$ para el que $n^2 - n + 11$ no es primo.|$n^2 - n + 11$ が素数でない最小の $n \ge 1$ を求めよ。|求使 $n^2 - n + 11$ 不是素数的最小 $n \ge 1$。`, sol: [R`n = 1, \dots, 10:\ 11, 13, 17, 23, 31, 41, 53, 67, 83, 101`, R`n = 11:\ 121 = 11^2`] } });

  Cheats.tutor('logic', L);
})();
